/**
 * Goods Received Notes (GRN/GRV) E2E Tests
 *
 * Covers: list page, new GRN form, API smoke tests.
 * Auth: uses storageState from tests/e2e/.auth/session.json (generated by auth.setup.ts)
 */

import { test, expect } from '@playwright/test';

// ─────────────────────────────────────────────────────────────────────────────
// API SMOKE TESTS
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Goods Received — API routes', () => {
  test('GET /api/accounting/goods-received responds (not 404)', async ({ request }) => {
    const res = await request.get('/api/accounting/goods-received');
    expect(res.status()).not.toBe(404);
    expect([200, 401]).toContain(res.status());
  });

  test('POST /api/accounting/goods-received with empty body returns 400 or 401', async ({ request }) => {
    const res = await request.post('/api/accounting/goods-received', { data: {} });
    expect([400, 401, 422]).toContain(res.status());
  });

  test('POST /api/accounting/goods-received missing purchaseOrderId returns 400 or 401', async ({ request }) => {
    const res = await request.post('/api/accounting/goods-received', {
      data: {
        receivedDate: '2024-01-01',
        items: [{ poItemId: '00000000-0000-0000-0000-000000000001', quantityReceived: 1 }],
      },
    });
    // purchaseOrderId is required — should reject
    expect([400, 401, 422]).toContain(res.status());
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// PAGE ROUTE SMOKE TESTS
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Goods Received — Page routes load', () => {
  for (const route of ['/accounting/goods-received', '/accounting/goods-received/new']) {
    test(`GET ${route} returns 200 or 307`, async ({ page }) => {
      const res = await page.goto(route);
      expect([200, 307]).toContain(res?.status() ?? 0);
    });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// GRN LIST PAGE
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Goods Received — List Page', () => {
  test.setTimeout(30000);

  test('shows "Goods Received Notes" heading', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');
    await expect(
      page.locator('h1', { hasText: /Goods Received Notes/i })
    ).toBeVisible();
  });

  test('has "New GRN" button linking to /accounting/goods-received/new', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    const btn = page.locator('button', { hasText: /New GRN/i }).first();
    await expect(btn).toBeVisible();
  });

  test('New GRN button navigates to the new GRN form', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    await page.locator('button', { hasText: /New GRN/i }).first().click();
    await page.waitForLoadState('networkidle');

    expect(page.url()).toMatch(/\/accounting\/goods-received\/new/);
  });

  test('has search input', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    await expect(
      page.locator('input[placeholder*="Search"]').first()
    ).toBeVisible();
  });

  test('page does not navigate to an error URL', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');
    expect(page.url()).not.toMatch(/error/i);
  });

  test('shows table column headers when GRNs exist', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    const count = await rows.count();
    if (count === 0) {
      test.skip(true, 'pending: no eligible test data — no GRN rows present to verify column headers');
      return;
    }

    for (const col of ['GRN #', 'PO Reference', 'Supplier', 'Received Date', 'Received By']) {
      await expect(page.locator('th', { hasText: col }).first()).toBeVisible();
    }
  });

  test('shows empty-state message when no GRNs are found', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    const count = await rows.count();
    if (count > 0) {
      test.skip(true, 'pending: no eligible test data — GRN rows are present so empty-state cannot be verified');
      return;
    }

    await expect(
      page.locator('text=No goods received notes found').first()
    ).toBeVisible();
  });

  test('GRN count in subtitle is a non-negative number', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    // The subtitle reads "N GRN(s)"
    const subtitle = page.locator('p').filter({ hasText: /\d+ GRN/i }).first();
    await expect(subtitle).toBeVisible();
  });

  test('search filters visible rows by GRN number', async ({ page }) => {
    await page.goto('/accounting/goods-received');
    await page.waitForLoadState('networkidle');

    const rows = page.locator('tbody tr');
    if (await rows.count() === 0) {
      test.skip(true, 'pending: no eligible test data — no GRN rows present to test search filtering');
      return;
    }

    // Type a search term that should match nothing
    await page.locator('input[placeholder*="Search"]').first().fill('XXXXXX-NOTEXIST');
    // The list is client-side filtered — no network request needed
    await expect(
      page.locator('text=No goods received notes found').first()
    ).toBeVisible({ timeout: 3000 });
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// NEW GRN FORM
// ─────────────────────────────────────────────────────────────────────────────

test.describe('Goods Received — New GRN Form', () => {
  test.setTimeout(30000);

  test('new GRN page renders without error', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');
    expect(page.url()).not.toMatch(/error/i);
  });

  test('form has a Purchase Order selector', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // PO selector is a <select> element populated from /api/accounting/purchase-orders?status=approved
    const poSelect = page.locator('select').first();
    await expect(poSelect).toBeVisible({ timeout: 10000 });
    const tag = await poSelect.evaluate((el) => el.tagName.toLowerCase());
    expect(tag).toBe('select');
  });

  test('form has a received date field pre-filled with today', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    const dateInput = page.locator('input[type="date"]').first();
    await expect(dateInput).toBeVisible({ timeout: 10000 });

    // Value should be set to today's date (not blank)
    const value = await dateInput.inputValue();
    expect(value).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  test('form has a Delivery Note / reference field', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // Delivery note is a text input (placeholder: "Delivery note number" or similar)
    const textInputs = page.locator('input[type="text"], input:not([type])');
    await expect(textInputs.first()).toBeVisible({ timeout: 10000 });
  });

  test('form has a Notes textarea or input', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // Notes field — could be textarea or input with placeholder "Notes"
    const notesField = page.locator('textarea, input[placeholder*="Notes"]').first();
    await expect(notesField).toBeVisible({ timeout: 10000 });
  });

  test('Cancel / Back button navigates back to GRN list', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // The form has an ArrowLeft back button in the header
    const backBtn = page.locator('button[title*="Back"], button:has(svg)').first();
    await backBtn.click();
    await page.waitForLoadState('networkidle');

    expect(page.url()).toMatch(/\/accounting\/goods-received$/);
  });

  test('submitting empty form shows validation error', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // Click the Record Receipt / Save button without selecting a PO
    const saveBtn = page.locator('button', {
      hasText: /Record Receipt|Save|Submit/i,
    }).first();

    if (await saveBtn.count() === 0) {
      test.skip(true, 'pending: no eligible test data — save/submit button not found in the form');
      return;
    }

    await saveBtn.click();

    // Should show an error message — "Please select a purchase order"
    await expect(
      page.locator('text=Please select a purchase order').first()
    ).toBeVisible({ timeout: 5000 });
  });

  test('PO selector shows approved POs or empty option', async ({ page }) => {
    await page.goto('/accounting/goods-received/new');
    await page.waitForLoadState('networkidle');

    // Wait for PO list to load (the select starts empty while loading)
    await page.waitForTimeout(1000);

    const poSelect = page.locator('select').first();
    await expect(poSelect).toBeVisible();

    // At minimum there should be a default/placeholder option
    const options = poSelect.locator('option');
    const optionCount = await options.count();
    expect(optionCount).toBeGreaterThanOrEqual(1);
  });
});
